-- TGDesk: base territorial oficial IBGE para o editor de regi?es.
-- Gerado da API IBGE Localidades em 2026-08-06: municipios nivelados e regioes metropolitanas.

CREATE TABLE IF NOT EXISTS brazil_municipalities (
    ibge_id INTEGER PRIMARY KEY,
    name TEXT NOT NULL,
    uf_id INTEGER NOT NULL,
    uf_sigla TEXT NOT NULL,
    uf_name TEXT NOT NULL,
    macroregion_id INTEGER NOT NULL,
    macroregion_sigla TEXT NOT NULL,
    macroregion_name TEXT NOT NULL,
    immediate_region_id INTEGER NOT NULL,
    immediate_region_name TEXT NOT NULL,
    intermediate_region_id INTEGER NOT NULL,
    intermediate_region_name TEXT NOT NULL,
    microregion_id INTEGER NOT NULL,
    microregion_name TEXT NOT NULL,
    mesoregion_id INTEGER NOT NULL,
    mesoregion_name TEXT NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS brazil_municipalities_uf_idx ON brazil_municipalities(uf_sigla, name);
CREATE INDEX IF NOT EXISTS brazil_municipalities_immediate_idx ON brazil_municipalities(immediate_region_id, name);
CREATE INDEX IF NOT EXISTS brazil_municipalities_intermediate_idx ON brazil_municipalities(intermediate_region_id, name);

CREATE TABLE IF NOT EXISTS brazil_metropolitan_areas (
    ibge_id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    uf_id INTEGER NOT NULL,
    uf_sigla TEXT NOT NULL,
    uf_name TEXT NOT NULL,
    macroregion_id INTEGER NOT NULL,
    macroregion_sigla TEXT NOT NULL,
    macroregion_name TEXT NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS brazil_metropolitan_area_municipalities (
    metropolitan_area_id TEXT NOT NULL REFERENCES brazil_metropolitan_areas(ibge_id) ON DELETE CASCADE,
    municipality_id INTEGER NOT NULL REFERENCES brazil_municipalities(ibge_id) ON DELETE CASCADE,
    PRIMARY KEY (metropolitan_area_id, municipality_id)
);

